head.script:
scwin.onpageload = function() {
    textbox1.setValue("이 값을 복사하여 input에 붙여넣어본다. alert이 뜨면 성공");
};
scwin.onpageunload = function() {};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    document.addEventListener("paste", function(e) {
        alert("복사 성공");
    });
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
